#!/usr/bin/env node
'use strict';

/**
 * scripts/generate-readme-tables.js — CLI entrypoint for the README table generator.
 *
 * Reads `config.json` (build config) and `README.md`, regenerates the
 * "Tested apps" and "Releases & Obtainium" tables, and:
 *   - default: writes them back into README.md between the marker pairs.
 *   - --check: regenerates in memory, diffs against what's currently
 *     between the markers, exits 0 if they match, non-zero with a
 *     readable diff if they don't (mirrors npm run validate:config).
 *
 * Markers used:
 *   <!-- BEGIN AUTOGENERATED: tested-apps -->     ...table...
 *   <!-- END   AUTOGENERATED: tested-apps -->
 *   <!-- BEGIN AUTOGENERATED: obtainium-table -->  ...table...
 *   <!-- END   AUTOGENERATED: obtainium-table -->
 *
 * Pure logic lives in .github/scripts/generate-readme-tables.js so the
 * Jest suite can exercise every rule without touching disk.
 */

const fs = require('node:fs');
const path = require('node:path');

const {
  buildTestedAppsTable,
  buildObtainiumTable,
  spliceReadmeBlocks,
  lineDiff,
} = require('../.github/scripts/generate-readme-tables.js');

function readJson(filePath) {
  return JSON.parse(fs.readFileSync(filePath, 'utf8'));
}

function main() {
  const args = process.argv.slice(2);
  const checkOnly = args.includes('--check');
  const root = path.resolve(__dirname, '..');
  const configPath = path.join(root, 'config.json');
  const readmePath = path.join(root, 'README.md');

  const config = readJson(configPath);
  const readme = fs.readFileSync(readmePath, 'utf8');

  const testedApps = buildTestedAppsTable(config);
  const obtainium = buildObtainiumTable(config);

  if (checkOnly) {
    // Recreate what the README *should* contain outside the markers by
    // splicing in the freshly generated tables. If the splice is
    // byte-identical to the current README, we are in sync.
    const expected = spliceReadmeBlocks(readme, testedApps, obtainium);
    if (expected === readme) {
      process.stdout.write('README tables are up to date.\n');
      process.exit(0);
    }
    process.stderr.write('README tables are OUT OF DATE. Regenerate with:\n');
    process.stderr.write('  node scripts/generate-readme-tables.js\n\n');
    process.stderr.write(lineDiff(expected, readme));
    process.stderr.write('\n');
    process.exit(1);
  }

  const next = spliceReadmeBlocks(readme, testedApps, obtainium);
  fs.writeFileSync(readmePath, next);
  process.stdout.write(
    `Regenerated "Tested apps" and "Releases & Obtainium" tables in README.md `
      + `(${Object.keys(config.patch_repos).length} app(s)).\n`,
  );
}

main();
